import { installCatalog } from './catalog.js';
 import { installOrders } from './orders.js';
 import { installBulk } from './bulk.js';
 import { requireStaff } from './auth.js';
 export function mount(router, env) {
   router.use(requireStaff);
   installCatalog(router);
   installOrders(router);
   if (env.NURSERY_BULK === 'enabled') installBulk(router);
 }

